"""Verify the master identity Stable(R) = Kernel(flip R) = GameSolution(flip R)."""
from __future__ import annotations
from itertools import combinations, chain
from typing import FrozenSet, Iterable, List, Set, Tuple

Relation = Set[Tuple[int, int]]

def flip(rel: Relation) -> Relation:
    return {(b, a) for (a, b) in rel}

def powerset(vs: Iterable[int]) -> Iterable[FrozenSet[int]]:
    xs = list(vs)
    return (frozenset(c) for c in chain.from_iterable(
        combinations(xs, k) for k in range(len(xs) + 1)))

def is_stable(rel: Relation, verts: List[int], s: FrozenSet[int]) -> bool:
    if any((a, b) in rel for a in s for b in s):
        return False
    return all(any((b, a) in rel for b in s) for a in verts if a not in s)

def is_kernel(dig: Relation, verts: List[int], s: FrozenSet[int]) -> bool:
    independent = all((a, b) not in dig for a in s for b in s)
    absorbing = all(any((a, b) in dig for b in s) for a in verts if a not in s)
    return independent and absorbing

if __name__ == "__main__":
    verts = [0, 1, 2, 3]
    R: Relation = {(0, 1), (1, 2), (3, 2)}
    stables = [s for s in powerset(verts) if is_stable(R, verts, s)]
    kernels = [s for s in powerset(verts) if is_kernel(flip(R), verts, s)]
    print("Stable(R)       :", [sorted(s) for s in stables])
    print("Kernel(flip R)  :", [sorted(s) for s in kernels])
    print("Coincide?       :", set(stables) == set(kernels))

"""Well-founded determinacy: unique kernel via the game recursion (Sprague-Grundy P-positions)."""
from __future__ import annotations
from itertools import combinations, chain
from typing import Dict, FrozenSet, Iterable, List, Set, Tuple

Relation = Set[Tuple[int, int]]

def out_neighbours(rel: Relation, a: int) -> Set[int]:
    return {b for (x, b) in rel if x == a}

def powerset(vs: Iterable[int]) -> Iterable[FrozenSet[int]]:
    xs = list(vs)
    return (frozenset(c) for c in chain.from_iterable(
        combinations(xs, k) for k in range(len(xs) + 1)))

def is_kernel(dig: Relation, verts: List[int], s: FrozenSet[int]) -> bool:
    independent = all((a, b) not in dig for a in s for b in s)
    absorbing = all(any((a, b) in dig for b in s) for a in verts if a not in s)
    return independent and absorbing

def losing_positions(move: Relation, verts: List[int]) -> FrozenSet[int]:
    memo: Dict[int, bool] = {}
    def is_loss(a: int) -> bool:
        if a in memo:
            return memo[a]
        memo[a] = False
        memo[a] = all(not is_loss(b) for b in out_neighbours(move, a))
        return memo[a]
    return frozenset(v for v in verts if is_loss(v))

if __name__ == "__main__":
    verts = list(range(10))
    move: Relation = {(n, n - d) for n in verts for d in (1, 2) if n - d >= 0}
    L = losing_positions(move, verts)
    kernels = [s for s in powerset(verts) if is_kernel(move, verts, s)]
    print("Losing positions (recursion):", sorted(L))
    print("All kernels (brute force)   :", [sorted(k) for k in kernels])
    print("Unique kernel = recursion?  :", kernels == [L])

