from __future__ import annotations
from typing import Dict, List, Set, Tuple

Relation = Set[Tuple[int, int]]

def kernel_by_game_recursion(move: Relation, verts: List[int]) -> Set[int]:
    """
    Compute the unique kernel {a : isLoss(a)} of a finite acyclic (well-founded)
    move relation by retrograde analysis: a position is a loss iff every move
    leads to a win.  Runs in O(|V| + |E|).
    """
    out: Dict[int, List[int]] = {v: [] for v in verts}
    for (a, b) in move:
        out[a].append(b)
    memo: Dict[int, bool] = {}

    def is_loss(a: int) -> bool:
        if a in memo:
            return memo[a]
        memo[a] = False  # placeholder; acyclicity guarantees no genuine reuse
        memo[a] = all(not is_loss(b) for b in out[a])
        return memo[a]

    return {v for v in verts if is_loss(v)}

