from __future__ import annotations
from typing import List, Set, Tuple

Relation = Set[Tuple[int, int]]

def flip(rel: Relation) -> Relation:
    return {(b, a) for (a, b) in rel}

def stable_extension_via_transpose(attack: Relation, verts: List[int]) -> Set[int]:
    """
    Compute the unique stable extension of a well-founded argumentation
    framework by reversing the attack edges and running the game recursion on
    the transpose.  Correct by the bridge Stable(R) = Kernel(flip R) and the
    well-founded uniqueness theorem.
    """
    move = flip(attack)
    out = {v: [b for (a, b) in move if a == v] for v in verts}
    memo = {}
    def is_loss(a: int) -> bool:
        if a in memo:
            return memo[a]
        memo[a] = False
        memo[a] = all(not is_loss(b) for b in out[a])
        return memo[a]
    return {v for v in verts if is_loss(v)}

